import { GRID, NPC_INTERACTION_RANGE } from '../game/GameConfig.js';

/**
 * Base class for non-hostile entities (Captives, Leshy, future NPCs)
 * Provides common functionality: pulsing animation, indicators, standard entity interface
 */
export class NeutralCharacter {
  constructor(char, color, x, y) {
    this.char = char;
    this.color = color;
    this.position = { x, y };
    this.width = GRID.CELL_SIZE;
    this.height = GRID.CELL_SIZE;
    this.velocity = { x: 0, y: 0 };

    // Pulsing animation
    this.pulseTimer = 0;
    this.pulseSpeed = 2.0;
    this.pulseMin = 0.7;
    this.pulseMax = 1.0;

    // Optional indicator (e.g., white '!' above character)
    this.indicator = null; // { char, color, offsetY }

    // True once DialogueSystem has opened this NPC's dialogue (gates flows
    // that should only unlock after the player has heard the NPC out).
    this.spokenOnce = false;

    // True while an activity owns SPACE near this speaker (the Weapons
    // Master's Parry Lesson): DialogueSystem.tryOpenNearby passes it over.
    this.talkSuspended = false;

    // True once a Cursed Run's Forsaken greeting has been told
    // (CursedRunSystem.greet) — the next SPACE opens the menu as normal.
    this.forsakenGreeted = false;

    // PERSUADE (InfluenceSystem): `persuadeOwner` names the game system that
    // gives this NPC's transaction away without its cost. An NPC without one
    // refuses with `persuadeRefusal`, and no wish is spent.
    this.persuadeOwner = null;
    this.persuadeRefusal = 'I HAVE NOTHING.';
  }

  update(deltaTime) {
    // Update pulse animation
    this.pulseTimer += deltaTime * this.pulseSpeed;
  }

  getPulseAlpha() {
    // Sine wave between pulseMin and pulseMax
    const sineWave = Math.sin(this.pulseTimer);
    return this.pulseMin + (sineWave + 1) * 0.5 * (this.pulseMax - this.pulseMin);
  }

  setIndicator(char, color, offsetY = -GRID.CELL_SIZE) {
    this.indicator = { char, color, offsetY };
  }

  // Single source of truth for "is the player close enough to interact with
  // this NPC" — used for dialogue, training, fishing, and every other
  // NPC-initiated SPACE interaction.
  isInRange(player, range = NPC_INTERACTION_RANGE) {
    if (!player) return false;
    const dist = Math.hypot(
      player.position.x - this.position.x,
      player.position.y - this.position.y
    );
    return dist < range;
  }

  // Speaking NPCs (those with getDialogueLines) call this each frame: shows a
  // '!' affordance in talk range, hidden while the dialogue box is open.
  updateTalkIndicator(game, range = NPC_INTERACTION_RANGE) {
    // A Scripted Event's `hold` owns its actor's indicator.
    if (game?.scriptedEventSystem?.run?.actor === this) return;
    const player = game?.player;
    if (this.isInRange(player, range) && !game.dialogueSystem?.isOpen()) {
      this.setIndicator('!', '#ffffff');
    } else {
      this.clearIndicator();
    }
  }

  clearIndicator() {
    this.indicator = null;
  }

  // Overridable render color hook (e.g. CampNPC's low-HP blink). Defaults to
  // the entity's base color.
  getDisplayColor() {
    return this.color;
  }

  getHitbox() {
    return {
      x: this.position.x - this.width / 2,
      y: this.position.y - this.height / 2,
      width: this.width,
      height: this.height
    };
  }

  render(ctx, gridToPixel) {
    const centerPixelPos = gridToPixel(
      this.position.x / GRID.CELL_SIZE,
      this.position.y / GRID.CELL_SIZE
    );

    ctx.save();
    ctx.font = `${GRID.CELL_SIZE}px 'Unifont', monospace`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    const pulseAlpha = this.getPulseAlpha();

    // Render main character with pulse
    ctx.globalAlpha = pulseAlpha;
    ctx.fillStyle = this.getDisplayColor();
    ctx.fillText(
      this.char,
      centerPixelPos.x + GRID.CELL_SIZE / 2,
      centerPixelPos.y + GRID.CELL_SIZE / 2
    );

    // Render indicator if present
    if (this.indicator) {
      const indicatorY = centerPixelPos.y + GRID.CELL_SIZE / 2 + this.indicator.offsetY;
      ctx.globalAlpha = 1.0;
      // A black cell behind the glyph: an NPC at the room's edge (Charon at the
      // north exit) has its indicator over the bright border wall.
      ctx.fillStyle = '#000000';
      ctx.fillRect(centerPixelPos.x, indicatorY - GRID.CELL_SIZE / 2, GRID.CELL_SIZE, GRID.CELL_SIZE);
      ctx.fillStyle = this.indicator.color;
      ctx.fillText(this.indicator.char, centerPixelPos.x + GRID.CELL_SIZE / 2, indicatorY);
    }

    ctx.restore();
  }
}
