export function getEnemyData(char) {
  return ENEMIES[char] || null;
}

// True-name lookup for CALL/COMMAND (see CommandSystem). Exact match against
// the registry's trueName field; returns the data block or null.
export function findEnemyDataByTrueName(trueName) {
  const wanted = (trueName || '').toUpperCase();
  if (!wanted) return null;
  return Object.values(ENEMIES).find(d => d.trueName === wanted) || null;
}

export function getSpawnTable(depth) {
  // Find the highest depth threshold that's <= current depth
  const thresholds = Object.keys(SPAWN_TABLES)
    .map(Number)
    .sort((a, b) => b - a);

  for (const threshold of thresholds) {
    if (depth >= threshold) {
      return SPAWN_TABLES[threshold];
    }
  }

  return SPAWN_TABLES[0];
}

export function getRandomEnemy(depth) {
  const table = getSpawnTable(depth);
  const char = table[Math.floor(Math.random() * table.length)];
  return char;
}

// Get random enemy for specific zone (zone-aware spawning)
// `excluded` lists Enemy chars a room keeps out of its random spawns (a letter
// template's `excludedEnemies`). Returns null when the exclusion empties the
// band, so callers skip the spawn.
export function getZoneRandomEnemy(depth, zoneType, excluded = null) {
  const zoneTables = ZONE_SPAWN_TABLES[zoneType];
  if (!zoneTables) {
    // Fallback to legacy depth-based spawning for unknown zones
    return getRandomEnemy(depth);
  }

  // Find highest depth threshold <= current depth
  const thresholds = Object.keys(zoneTables)
    .map(Number)
    .sort((a, b) => b - a);

  let table = zoneTables[0];
  for (const threshold of thresholds) {
    if (depth >= threshold) {
      table = zoneTables[threshold];
      break;
    }
  }

  if (excluded?.length) table = table.filter(c => !excluded.includes(c));
  if (table.length === 0) return null;
  return table[Math.floor(Math.random() * table.length)];
}

// Boss enemies (2x stats). Zone-aware: B-room fallbacks must pull from the
// zone's own table, not the legacy depth table (off-theme spawns otherwise).
export function createBossEnemy(depth, zoneType = null) {
  const baseChar = zoneType ? getZoneRandomEnemy(depth, zoneType) : getRandomEnemy(depth);
  const baseData = getEnemyData(baseChar);

  return {
    ...baseData,
    hp: baseData.hp * 2,
    damage: baseData.damage * 2,
    isBoss: true,
    color: '#ff00ff'
  };
}

