import { GRID, GAME_STATES, ZOOM } from '../game/GameConfig.js';
import { isDeathHeldOffSurface, isInteriorActive, activeInteriorFloor } from './PlaneSystem.js';
import { isConcealedEnemy } from './enemyConcealment.js';

// Time constant (seconds) of a scripted frame's pan toward a moved focus:
// ~95% of the way there in three of these.
const SCRIPTED_FOCUS_EASE_SECONDS = 0.3;
// Time constants of a fitted hold's scale (holdZoom with a scale function).
// Opening out matches the pan, so a body heading for the edge stays in frame;
// closing back in is four times slower, so a gap that opens and shuts in a
// moment barely moves the frame instead of pumping it in and out.
const SCRIPTED_FIT_OUT_SECONDS = 0.3;
const SCRIPTED_FIT_IN_SECONDS = 1.2;

/**
 * CameraZoomSystem — combat-proximity camera zoom.
 *
 * Zooms the view to ZOOM.SCALE, framed on the player, whenever an aggro'd
 * enemy is within ZOOM.TRIGGER_RANGE_CELLS of the player during EXPLORE —
 * aggro, not mere proximity: an enemy currently fleeing (State Flee/Lookback
 * — Rat post-steal, Trap Goblin, a still-growing Bomb) is a coward, not a
 * threat, and wandering close to one shouldn't zoom the camera in. Once zoomed,
 * stays zoomed until the nearest threat clears the wider
 * ZOOM.RELEASE_RANGE_CELLS (hysteresis, avoids flicker at the boundary)
 * and no threat is left inside the zoomed frame — an enemy the player can
 * still see keeps the frame (and its Motif) engaged. However soon that
 * happens, a zoom-in holds at least ZOOM.MIN_ZOOMED_MS, so the frame can't
 * pump in and out. That hold (and the ZOOM.ZOOM_OUT_DELAY_MS gap hold) only
 * starts counting once the frame has finished easing in: a threat that clears
 * mid-zoom-in cancels it, and the frame eases back out from where it was.
 * A concealed enemy (isConcealedEnemy) is no threat to the frame, and the
 * Ancient Shell's phase 2 holds it fully open (BossSystem.holdsFrameOpen).
 * Inside the Maze interior, zoom is forced on permanently at the tighter
 * ZOOM.MAZE_SCALE regardless of ghost proximity — the corridor is narrow enough
 * that it's always relevant. A worn Compass doesn't open it: its needle points
 * to the Maze's center instead (CompassSystem.getNeedleTarget).
 * On the surface with no weapon equipped, the same trigger instead targets
 * ZOOM.HALF_SCALE — still some tension from the nearby threat, but not the
 * full commit of an armed engagement; Interiors are exempt from this
 * downgrade since their zoom isn't threat-driven to begin with.
 *
 * Framing keeps the player centered by default, but clamps the on-screen
 * center so the fully-zoomed-in viewport never pans past the current
 * room/interior's own rendered rect — which already includes its
 * border-wall ring, since those walls occupy the outermost cell of that same
 * grid (RoomGenerator's border-wall pass). The player only ever ends up
 * off-center when the clamp is actively holding the frame against a wall.
 * The clamp is always solved against the fully-zoomed-in scale (_frameScale),
 * not the live easing value the zoom-in/out transition is currently at —
 * that pivot is provably still in-bounds at every lesser scale too (see
 * _computeClampedOrigin), so the pivot stays put and only the scale eases,
 * instead of the pivot itself snapping/sliding as the transition plays out.
 * Runs on the surface and inside every Interior (Hut/Dungeon/Maze) alike, since
 * all of them render onto the same two canvas elements the zoom transform
 * scales (RenderController.applyCameraEffects).
 *
 * Updated unconditionally every frame (not gated inside updateExploreState) so
 * it can ease back to 1.0 if the player leaves EXPLORE or an Interior while
 * zoomed in, rather than leaving REST/NEUTRAL views stuck zoomed. The pivot
 * origin is only recomputed while actively tracking the player (EXPLORE/
 * Interior); on leaving that state it holds its last value instead of
 * snapping to canvas-center, so a still-elevated zoom eases from the pivot
 * it was actually zoomed on rather than jump-cutting the framing on the same
 * frame the state changes. Player death (GAME_OVER) additionally uses a
 * much shorter transition (ZOOM.TRANSITION_DEATH_MS) than a normal combat
 * disengage — the death screen needs to read at 1.0 quickly, not ease out
 * at the same leisurely pace as walking away from a fight.
 *
 * A scripted scene can take the frame over with holdZoom(scale, focus) — every
 * trigger above is ignored until releaseZoom(). The Grasp holds the climb
 * fully open at 1.0 and ends Act 1 by easing in on the Trine (GraspSystem);
 * through Act 2 that hold is fitted — its scale follows the bodies still
 * standing, out as they spread and back in as they close.
 * Entering TITLE snaps the frame open instead of easing (reset()).
 */
export class CameraZoomSystem {
  constructor(game) {
    this.game = game;
    this.currentZoom = 1;
    this.startZoom = 1;
    this.targetZoom = 1;
    this.elapsedMs = 0;
    this.originXPercent = 50;
    this.originYPercent = 50;
    this._noEnemyElapsedMs = Infinity;
    // How long the combat trigger has wanted the zoom since it last zoomed
    // in; it can't release before ZOOM.MIN_ZOOMED_MS (Infinity = not zoomed).
    this._zoomedElapsedMs = Infinity;
    this._lastThreats = []; // _rememberThreats: last frame's threats
    this._lastState = null;
    // A scripted frame (holdZoom): { scale, focus, at } where focus() returns
    // the canvas-pixel point to frame on, or null to keep the player as the
    // focus, and `at` is where the frame is actually centered — it eases
    // toward focus() (_easeScriptedFocus) so a jump in the focus is a pan,
    // not a cut. A fitted hold also carries `fit`, its eased scale.
    this.scripted = null;
  }

  /**
   * Take the frame out of the combat trigger's hands: ease to `scale` framed
   * on `focus()` (canvas pixels; omitted = the player) until releaseZoom().
   * Scale 1 holds the frame fully open — a scripted scene that needs the
   * whole room on screen (the Grasp's climb) uses it that way. `scale` may
   * instead be a function, read every frame: a fitted hold, whose scale the
   * camera eases toward it (_fitScriptedScale) — the scene says how tight
   * the frame can be, the camera decides how fast it gets there.
   */
  holdZoom(scale, focus = null) {
    this.scripted = { scale, focus, at: null, fit: null };
  }

  /** Hand the frame back to the combat trigger. */
  releaseZoom() {
    this.scripted = null;
  }

  /**
   * Snap the frame fully open with no easing and no scripted hold
   * (RESET_REGISTRY `cameraZoomSystem.reset`, title scope). TITLE and the
   * attract-mode demo it leads into are a fresh scene, not a camera move:
   * a frame still zoomed from the run before (the Mist Battle's Act 2 ends
   * held tight on the Trine) must not ease out over the title.
   */
  reset() {
    this.scripted = null;
    this.currentZoom = 1;
    this.startZoom = 1;
    this.targetZoom = 1;
    this.elapsedMs = 0;
    this.originXPercent = 50;
    this.originYPercent = 50;
    this._noEnemyElapsedMs = Infinity;
    this._zoomedElapsedMs = Infinity;
    this._lastThreats = [];
  }

  /** True once the frame has finished easing to its current target. */
  isZoomSettled() {
    return this.currentZoom === this.targetZoom;
  }

  update(deltaTime) {
    const game = this.game;
    const player = game.player;
    const state = game.stateMachine.getCurrentState();

    // Freshly entering GAME_OVER forces a rapid restart of the zoom-out even
    // if the target was already 1 (e.g. death interrupts a normal in-progress
    // disengage) — without this, the leftover elapsed time from the slower
    // transition would carry over and mis-time the rapid one.
    const justDied = state === GAME_STATES.GAME_OVER && this._lastState !== GAME_STATES.GAME_OVER;
    this._lastState = state;

    let desiredScale = 1;

    if (state === GAME_STATES.EXPLORE && player) {
      const { entities, gridCols, gridRows } = this._resolveActiveLayer(game, player);

      const { x: offsetX, y: offsetY } = layerCanvasOffset(gridCols, gridRows);
      const canvasX = offsetX + player.position.x + player.width / 2;
      const canvasY = offsetY + player.position.y + player.height / 2;
      const desiredXPercent = (canvasX / GRID.WIDTH) * 100;
      const desiredYPercent = (canvasY / GRID.HEIGHT) * 100;

      // Clamp bounds are the room/interior's own rendered rect (in canvas
      // percent) — this already includes the border-wall ring at its edges,
      // so the frame is free to push all the way up to the wall rather than
      // stopping short of it.
      const roomLeftPercent = (offsetX / GRID.WIDTH) * 100;
      const roomRightPercent = ((offsetX + gridCols * GRID.CELL_SIZE) / GRID.WIDTH) * 100;
      const roomTopPercent = (offsetY / GRID.HEIGHT) * 100;
      const roomBottomPercent = ((offsetY + gridRows * GRID.CELL_SIZE) / GRID.HEIGHT) * 100;

      // Clamp against the fully-zoomed-in scale (_frameScale), not the live
      // easing value from _tickZoom — that's what "lock to the edge on full
      // zoom-in" actually means, and it's what keeps the pivot stable across
      // the whole transition instead of recomputing a shrinking/growing clamp
      // window every frame. A pivot solved against a wider (less-zoomed)
      // window would still be valid at full zoom, but a pivot solved against
      // the fully-zoomed window is provably still in-bounds at every lesser
      // scale too (the visible window only ever narrows as scale grows), so
      // fixing on that scale is the one choice that's smooth at every step:
      // the pivot barely moves once computed, and only the scale eases.
      const frameScale = this._frameScale(player);
      this.originXPercent = this._computeClampedOrigin(desiredXPercent, roomLeftPercent, roomRightPercent, frameScale);
      this.originYPercent = this._computeClampedOrigin(desiredYPercent, roomTopPercent, roomBottomPercent, frameScale);

      // Hysteresis: once zoomed in, require the enemy to clear the wider
      // release range before we zoom back out, so it doesn't flicker in/out
      // as an enemy hovers right at the trigger boundary. A threat still
      // inside the zoomed frame also holds the zoom: the frame reaches ~8.5
      // cells to each edge (more diagonally or against a wall) — past the
      // release range — and releasing on an enemy the player can still see
      // also cut its Motif while it was on screen.
      const zoomed = this.targetZoom !== 1;
      const rangeCells = zoomed
        ? ZOOM.RELEASE_RANGE_CELLS
        : ZOOM.TRIGGER_RANGE_CELLS;
      const enemyDetected = this._enemyNearby(player, entities, rangeCells)
        || (zoomed && this._threatInFrame(entities, this.targetZoom));

      // Extra hold: once no enemy is detected, keep the zoomed frame for
      // ZOOM.ZOOM_OUT_DELAY_MS before actually releasing, so a momentary
      // gap in detection doesn't snap the camera out and back in.
      // Not when the gap is a threat hiding itself: a Sniper that vanishes
      // after its shot (or any enemy turning Invisible) would otherwise keep
      // the frame zoomed on nothing for the hold, which gives the hiding away.
      // An enemy that hid this frame releases the zoom at once.
      //
      // Minimum hold: once zoomed in, the frame stays in for
      // ZOOM.MIN_ZOOMED_MS however soon the threat clears, so a fight at the
      // edge of the trigger range can't pump the camera in and out. A threat
      // that hid itself still releases at once, for the same reason as above.
      //
      // Neither hold applies to a zoom still easing in: a threat that clears
      // before the frame has arrived cancels the zoom-in, and the frame eases
      // back out from wherever it was caught, instead of finishing the
      // zoom-in and then holding on nothing.
      const threatHid = !enemyDetected && this._aThreatJustHid();
      const easingIn = this.targetZoom > 1 && this.currentZoom < this.targetZoom;
      const holdsApply = !threatHid && !easingIn;
      if (enemyDetected) {
        this._noEnemyElapsedMs = 0;
      } else if (threatHid) {
        this._noEnemyElapsedMs = ZOOM.ZOOM_OUT_DELAY_MS;
      } else {
        this._noEnemyElapsedMs += deltaTime * 1000;
      }
      this._rememberThreats(entities);
      if (enemyDetected && this._zoomedElapsedMs === Infinity) this._zoomedElapsedMs = 0;
      else if (this._zoomedElapsedMs !== Infinity) this._zoomedElapsedMs += deltaTime * 1000;
      const heldIn = holdsApply && this._zoomedElapsedMs < ZOOM.MIN_ZOOMED_MS;
      const delayHeld = holdsApply && this._noEnemyElapsedMs < ZOOM.ZOOM_OUT_DELAY_MS;
      const wantsZoom = enemyDetected || heldIn || delayHeld;
      // Released: both holds are spent. A zoom-in cancelled mid-ease would
      // otherwise find its gap delay still running on the next frame (the
      // target is 1 now, so it no longer reads as easing in) and zoom right
      // back in, flip-flopping the target until the delay ran out.
      if (!wantsZoom) {
        this._zoomedElapsedMs = Infinity;
        this._noEnemyElapsedMs = Math.max(this._noEnemyElapsedMs, ZOOM.ZOOM_OUT_DELAY_MS);
      }
      desiredScale = wantsZoom ? ZOOM.SCALE : 1;

      // Maze interiors stay permanently zoomed in, regardless of ghost
      // proximity.
      if (player.inMaze) desiredScale = ZOOM.MAZE_SCALE;

      // On the surface with no weapon equipped, an aggro'd enemy nearby still
      // reads as some tension, but not a full combat commit — half zoom
      // instead of the full scale, rather than suppressing the zoom outright.
      // Interiors (Maze/Hut/Dungeon) are exempt from this downgrade — their
      // zoom isn't threat-driven to begin with.
      if (!player.heldItem && !isInteriorActive(game)) {
        desiredScale = desiredScale === ZOOM.SCALE ? ZOOM.HALF_SCALE : 1;
      }

      // Centipede miniboss: the arena is large and densely packed with fixed
      // obstacles, and the encounter can span many on-screen chain segments
      // at once — zooming in would clip parts of the chain off-screen
      // (isEntityOnScreen gates committed attacks) and shrink the player's
      // view of the obstacle field the chain is bouncing around in.
      if (game.currentRoom?.centipedeChains?.length) desiredScale = 1;

      // A boss phase that spans the whole arena (the Ancient Shell's phase-2
      // ricochet) holds the frame open for the rest of the fight.
      if (game.bossSystem?.holdsFrameOpen() && !isInteriorActive(game)) desiredScale = 1;

      // A scripted frame overrides every trigger above, focus included.
      if (this.scripted) {
        desiredScale = this._scriptedScale(deltaTime);
        const focus = this._easeScriptedFocus(deltaTime);
        if (focus && desiredScale > 1) {
          this.originXPercent = this._computeClampedOrigin((focus.x / GRID.WIDTH) * 100, roomLeftPercent, roomRightPercent, desiredScale);
          this.originYPercent = this._computeClampedOrigin((focus.y / GRID.HEIGHT) * 100, roomTopPercent, roomBottomPercent, desiredScale);
        }
      }
    } else if (state === GAME_STATES.GAME_OVER && isDeathHeldOffSurface(game)) {
      // Death underground / inside an Interior reads in place first: keep the
      // zoom (and pivot) exactly as it was at the moment of death until the
      // view cuts to the surface GAME OVER screen, then release rapidly.
      desiredScale = this.targetZoom;
    } else {
      this._noEnemyElapsedMs = Infinity;
      this._zoomedElapsedMs = Infinity;
      this._lastThreats = [];
      // Origin deliberately left untouched here — see class doc comment.
    }

    this._tickZoom(desiredScale, deltaTime, state, justDied);
  }

  // The scripted frame's center, eased toward its focus(). A focus can jump —
  // the Mist Battle's Act 2 frames the centroid of the bodies still standing,
  // so it leaps the moment one falls — and a snapped pivot would cut the
  // frame. The first point is taken as-is, so a hold starts where it aims.
  _easeScriptedFocus(deltaTime) {
    const target = this.scripted.focus?.();
    if (!target) return this.scripted.at;
    const at = this.scripted.at;
    if (!at) {
      this.scripted.at = { x: target.x, y: target.y };
    } else {
      const k = 1 - Math.exp(-deltaTime / SCRIPTED_FOCUS_EASE_SECONDS);
      at.x += (target.x - at.x) * k;
      at.y += (target.y - at.y) * k;
    }
    return this.scripted.at;
  }

  // The scripted frame's scale this frame. A fitted hold opens on the usual
  // eased transition (_tickZoom), aimed at its first fit; once that settles
  // the scale follows the fit itself, eased here, and current and target
  // move together — _tickZoom's fixed-length transition would restart every
  // frame against a target that moves every frame, and crawl.
  _scriptedScale(deltaTime) {
    const s = this.scripted;
    const want = typeof s.scale === 'function' ? s.scale() : s.scale;
    if (typeof s.scale !== 'function') return want;
    if (s.fit === null) {
      s.fit = want;
      return want;
    }
    if (this.currentZoom !== this.targetZoom) return this.targetZoom;
    const tau = want < s.fit ? SCRIPTED_FIT_OUT_SECONDS : SCRIPTED_FIT_IN_SECONDS;
    s.fit += (want - s.fit) * (1 - Math.exp(-deltaTime / tau));
    this.currentZoom = this.targetZoom = this.startZoom = s.fit;
    return s.fit;
  }

  /** The tightest scale this layer's frame can reach. */
  _frameScale(player) {
    return player.inMaze ? ZOOM.MAZE_SCALE : ZOOM.SCALE;
  }

  /** Live threat list + local grid size for the player's current layer. */
  _resolveActiveLayer(game, player) {
    if (player.inMaze && game.mazeInterior) {
      return {
        entities: [...game.mazeInterior.ghosts, ...game.mazeInterior.enemies],
        gridCols: game.mazeInterior.gridCols,
        gridRows: game.mazeInterior.gridRows
      };
    }
    const floor = activeInteriorFloor(game);
    if (floor) {
      return {
        entities: floor.enemies,
        gridCols: floor.gridCols,
        gridRows: floor.gridRows
      };
    }
    return {
      entities: game._activeEnemies(),
      gridCols: GRID.COLS,
      gridRows: GRID.ROWS
    };
  }

  // Keep-centered-with-edge-lock framing. `desiredCenterPercent` is where the
  // player sits in canvas-percent (what the frame would center on with no
  // constraint); `roomStartPercent`/`roomEndPercent` bound the room/interior's
  // own rendered rect on this axis (inclusive of its border-wall ring — see
  // class doc comment); `scale` is always called with _frameScale (the target
  // fully-zoomed-in scale), never the live easing value — see call site.
  // Returns a CSS transform-origin percent: the point that stays pinned
  // under `scale()` so the clamped center lands at screen-center (50%).
  //
  // Derivation: under `transform-origin: O; scale(s)`, a canvas point at
  // fraction f is drawn at screen fraction O + (f - O) * s. Solving for the O
  // that puts a target fraction C at screen-center (50) gives
  // O = (C*s - 50) / (s - 1). At s == 1 the transform is the identity and O
  // is irrelevant, so it's returned as-is to avoid the s==1 singularity.
  //
  // Why solving at the frame scale stays in-bounds at every lesser scale too:
  // for a fixed O, the visible window at an arbitrary actual scale a is
  // [O*(1 - 1/a), O + (100 - O)/a]. Since O and (100 - O) are both >= 0 and
  // 1/a <= 1 for every a >= 1, the left edge is always >= 0 and the right
  // edge is always <= 100 — true for any a, not just the frame scale. So a
  // pivot that's correctly clamped for the tightest (most-zoomed-in) window
  // is automatically still fully in-bounds for every wider window the
  // zoom-in/out transition passes through on the way there.
  _computeClampedOrigin(desiredCenterPercent, roomStartPercent, roomEndPercent, scale) {
    const halfWindowPercent = 50 / scale;
    const lowerBound = roomStartPercent + halfWindowPercent;
    const upperBound = roomEndPercent - halfWindowPercent;
    // Room narrower than the zoom window on this axis (small interior at
    // high zoom): centering is impossible either way, so just hold the
    // room's own center rather than let the bounds invert.
    const clampedCenter = lowerBound > upperBound
      ? (roomStartPercent + roomEndPercent) / 2
      : Math.min(upperBound, Math.max(lowerBound, desiredCenterPercent));

    if (Math.abs(scale - 1) < 1e-6) return clampedCenter;
    return (clampedCenter * scale - 50) / (scale - 1);
  }

  _enemyNearby(player, entities, rangeCells) {
    if (!entities || entities.length === 0) return false;
    const range = rangeCells * GRID.CELL_SIZE;
    const px = player.position.x + player.width / 2;
    const py = player.position.y + player.height / 2;
    return entities.some((e) => {
      if (!isThreat(e)) return false;
      const ex = e.position.x + (e.width ?? GRID.CELL_SIZE) / 2;
      const ey = e.position.y + (e.height ?? GRID.CELL_SIZE) / 2;
      return Math.hypot(ex - px, ey - py) <= range;
    });
  }

  // The entities that counted as threats this frame, kept to the next so a
  // threat that turns concealed can be told from one that walked away.
  _rememberThreats(entities) {
    this._lastThreats = (entities ?? []).filter(isThreat);
  }

  // Whether a threat from last frame is now alive but concealed (Invisible,
  // shelled, faded into grass): it hid rather than left.
  _aThreatJustHid() {
    return this._lastThreats.some((e) => (e.hp === undefined || e.hp > 0) && isConcealedEnemy(e));
  }

  // Whether any threat sits inside the frame the zoom is committed to.
  // Judged at the target scale, not the live easing value, so a zoom that
  // has only just started easing in (still near 1.0, where everything
  // counts as on-screen) doesn't hold itself open on the whole room.
  _threatInFrame(entities, scale) {
    if (!entities || entities.length === 0) return false;
    return entities.some((e) => isThreat(e) && this.isEntityOnScreen(e, scale));
  }

  _tickZoom(desiredScale, deltaTime, state, forceRestart) {
    if (desiredScale !== this.targetZoom || forceRestart) {
      this.startZoom = this.currentZoom;
      this.targetZoom = desiredScale;
      this.elapsedMs = 0;
    }

    if (this.currentZoom === this.targetZoom) return;

    // Zoom-in and a normal zoom-out share the same eased duration. Player
    // death is a rapid correction instead — see class doc comment. Compared
    // against startZoom (not a fixed ZOOM.SCALE check) so this still picks
    // the right direction now that the target can also land at ZOOM.HALF_SCALE
    // (unequipped surface exploration) rather than only 1 or ZOOM.SCALE.
    const zoomingIn = this.targetZoom > this.startZoom;
    const durationMs = zoomingIn
      ? ZOOM.TRANSITION_IN_MS
      : state === GAME_STATES.GAME_OVER
        ? ZOOM.TRANSITION_DEATH_MS
        : ZOOM.TRANSITION_OUT_MS;

    this.elapsedMs = Math.min(durationMs, this.elapsedMs + deltaTime * 1000);
    const t = this.elapsedMs / durationMs;
    const eased = cubicBezierEase(t);
    this.currentZoom = this.startZoom + (this.targetZoom - this.startZoom) * eased;
  }

  getScale() {
    return this.currentZoom;
  }

  /**
   * True while the camera is committed to a zoomed frame (full or half
   * scale) — from the moment it starts easing in until it starts easing out.
   */
  isZoomEngaged() {
    return this.targetZoom > 1;
  }

  /**
   * The entities on the player's current layer (surface enemies, an
   * Interior floor's enemies, or the Maze's ghosts) — the same list the
   * zoom trigger reads.
   */
  activeLayerEntities() {
    const player = this.game.player;
    if (!player) return [];
    return this._resolveActiveLayer(this.game, player).entities ?? [];
  }

  getOriginPercent() {
    return { x: this.originXPercent, y: this.originYPercent };
  }

  // An entity's center in CANVAS pixels — the space the zoom origin lives in.
  // Interior floors (Dungeon/Hut) and the Maze are smaller than the surface
  // grid and drawn centered on the canvas, so their entities' positions are
  // interior-local and need the same centering offset update() applies to the
  // player. Without it every interior enemy was projected up to ~3 cells
  // up-left of where it is drawn: judged off-screen while standing next to
  // the player near a top/left wall, which aborted its Strike every frame and
  // left it frozen in place (bug #398).
  entityCanvasCenter(entity) {
    const game = this.game;
    const player = game.player;
    let offset = { x: 0, y: 0 };
    if (player && game.stateMachine.getCurrentState() === GAME_STATES.EXPLORE) {
      const { gridCols, gridRows } = this._resolveActiveLayer(game, player);
      offset = layerCanvasOffset(gridCols, gridRows);
    }
    return {
      x: offset.x + entity.position.x + (entity.width ?? GRID.CELL_SIZE) / 2,
      y: offset.y + entity.position.y + (entity.height ?? GRID.CELL_SIZE) / 2
    };
  }

  // Whether `entity` falls inside the visible canvas under the current zoom
  // transform. At scale 1 (no zoom) everything is on-screen by definition.
  // Same projection OffscreenEnemyIndicators uses to place its edge arrows —
  // kept here as the single source of truth so combat code (committed
  // windups/telegraphs that must not fire on an enemy the player can't see)
  // and that renderer agree on what "visible" means.
  // `scale` defaults to the live zoom; the release check passes the target.
  isEntityOnScreen(entity, scale = this.currentZoom) {
    if (scale <= 1) return true;
    const ox = (this.originXPercent / 100) * GRID.WIDTH;
    const oy = (this.originYPercent / 100) * GRID.HEIGHT;
    const { x: ex, y: ey } = this.entityCanvasCenter(entity);
    const screenX = ox + (ex - ox) * scale;
    const screenY = oy + (ey - oy) * scale;
    return screenX >= 0 && screenX <= GRID.WIDTH && screenY >= 0 && screenY <= GRID.HEIGHT;
  }
}

// Whether an entity counts toward the combat zoom: alive, not a pacifist,
// not concealed, and not a coward — an enemy currently running away (State
// Flee) or glancing back mid-flight (State Lookback) is disengaging, not
// aggro, and doesn't warrant the combat-tension zoom just because the player
// happens to be nearby. A concealed enemy (a Tortoise tucked in its shell
// passing for a rock, a mimic, a sniper or anything faded into tall grass —
// isConcealedEnemy) doesn't zoom the frame either: the zoom would give the
// disguise away, the same reason offscreen arrows and LOOKHERE skip it.
// Entities without a spine (e.g. Maze ghosts) fall through unaffected via
// the optional chain.
function isThreat(e) {
  if (e.hp !== undefined && e.hp <= 0) return false;
  if (e.data?.pacifist) return false;
  if (isConcealedEnemy(e)) return false;
  const spineState = e.stateMachine?.current;
  return spineState !== 'flee' && spineState !== 'lookback';
}

// Canvas-pixel offset of a gridCols x gridRows layer drawn centered on the
// canvas (zero for the full-size surface grid).
function layerCanvasOffset(gridCols, gridRows) {
  return {
    x: Math.floor((GRID.WIDTH - gridCols * GRID.CELL_SIZE) / 2),
    y: Math.floor((GRID.HEIGHT - gridRows * GRID.CELL_SIZE) / 2)
  };
}

// Standard CSS "ease-in-out" cubic bezier — control points (0.42, 0), (0.58, 1).
// Solved via Newton-Raphson on the bezier's x(t) so the eased value is driven by
// true bezier progress rather than a polynomial ease approximation.
const BEZIER_X1 = 0.42, BEZIER_Y1 = 0;
const BEZIER_X2 = 0.58, BEZIER_Y2 = 1;

function bezierComponent(t, p1, p2) {
  const mt = 1 - t;
  return 3 * mt * mt * t * p1 + 3 * mt * t * t * p2 + t * t * t;
}

function bezierComponentDerivative(t, p1, p2) {
  const mt = 1 - t;
  return 3 * mt * mt * p1 + 6 * mt * t * (p2 - p1) + 3 * t * t * (1 - p2);
}

function solveBezierT(x) {
  let t = x;
  for (let i = 0; i < 8; i++) {
    const currentX = bezierComponent(t, BEZIER_X1, BEZIER_X2) - x;
    const derivative = bezierComponentDerivative(t, BEZIER_X1, BEZIER_X2);
    if (Math.abs(derivative) < 1e-6) break;
    t -= currentX / derivative;
    t = Math.min(1, Math.max(0, t));
  }
  return t;
}

function cubicBezierEase(x) {
  if (x <= 0) return 0;
  if (x >= 1) return 1;
  const t = solveBezierT(x);
  return bezierComponent(t, BEZIER_Y1, BEZIER_Y2);
}
