import { Ingredient } from '../entities/Ingredient.js';
import { Item } from '../entities/Item.js';
import { isIngredient, isItem, generateEnemyDrops, resolvePickupSfx, GEM_CHARS } from '../data/items.js';
import { planeOf, lootOnActiveLayer, tagLootLayer } from './PlaneSystem.js';
import { GRID, GAME_STATES, PHYSICS } from '../game/GameConfig.js';
import { STARTER_POTION_CHARS, starterPotionIngredientsFor } from '../data/alchemy.js';
import { isPileCapped } from './IngredientPile.js';
import { slideLootOffRestSlots } from './restSlotClearance.js';
import { slideLootOffWalls, pullPathClear } from './lootWallClearance.js';
import { hasLuckBlessing, coinDropChance } from './luck.js';

// Chance each Coin an enemy drops becomes a Frog Coin while the player is in frog form.
const FROG_COIN_SWAP_CHANCE = 0.25;
// Chance the universal Coin drop comes up an Empty Bottle instead — bottles
// had no general enemy source (only goo's uncommon pool, ~0.4% per kill).
const BOTTLE_FOR_COIN_CHANCE = 0.10;

export class LootSystem {
  constructor(game) {
    this.game = game;
  }

  // Canonical ingredient grant — routes special pickups (Emerald Robe goo heal,
  // active-meter mana refill), otherwise drops the glyph into the one pile via
  // game.addIngredient, then removes the ingredient from the world. Shared by
  // the player attraction pickup in all three states and the boomerang fetch.
  updateIngredientSeparation(deltaTime) {
    const game = this.game;
    // Loot parked on a REST slot hides under it and steals its SPACE.
    if (game.stateMachine.getCurrentState() === GAME_STATES.REST) slideLootOffRestSlots(game, deltaTime);
    // Loot thrown into a wall (or past an Interior's edge) slides back out.
    slideLootOffWalls(game, deltaTime);
    const ingredients = game.ingredients;
    const player = game.player;
    const sep = GRID.CELL_SIZE * 1.2;
    for (let i = ingredients.length - 1; i >= 0; i--) {
      const ingredient = ingredients[i];
      if (ingredient.pickupCooldown > 0) {
        ingredient.pickupCooldown = Math.max(0, ingredient.pickupCooldown - deltaTime);
      }
      if (ingredient.dropBounceTimer > 0) {
        ingredient.dropBounceTimer = Math.max(0, ingredient.dropBounceTimer - deltaTime);
      }
      for (let j = i - 1; j >= 0; j--) {
        const other = ingredients[j];
        const dx = ingredient.position.x - other.position.x;
        const dy = ingredient.position.y - other.position.y;
        const distSq = dx * dx + dy * dy;
        if (distSq < sep * sep && distSq > 0.01) {
          const dist = Math.sqrt(distSq);
          const force = (sep - dist) * 40;
          const nx = dx / dist, ny = dy / dist;
          ingredient.velocity.vx += nx * force * deltaTime;
          ingredient.velocity.vy += ny * force * deltaTime;
          other.velocity.vx -= nx * force * deltaTime;
          other.velocity.vy -= ny * force * deltaTime;
        }
      }
      // Pile-capped for this char (coins never cap — they live in the
      // wallet, not the pile): stop pulling it toward the player instead of
      // dragging it in only to have collectIngredient bounce it right back.
      const capped = ingredient.char !== 'c'
        && isPileCapped(ingredient.char, game.countIngredient(ingredient.char));
      // The interior-overlay tags (hutPlane / mazePlane — distinct from the
      // surface/tunnel .plane field) — an ingredient tagged for one layer must
      // not be reachable from another, same as the render-side filters enforce.
      const wrongLayer = !lootOnActiveLayer(game, ingredient);
      // A wall between it and the player: no pull (it would drag the
      // ingredient into the wall, and the wall slide would push it back out).
      // Only swept inside magnet range — out of range there is no pull anyway.
      const inRange = Math.hypot(player.position.x - ingredient.position.x,
        player.position.y - ingredient.position.y) < PHYSICS.ATTRACTION_RADIUS;
      const walledOff = inRange && !wrongLayer && !pullPathClear(game, ingredient, player);
      if (capped || wrongLayer || walledOff) {
        ingredient.acceleration = { ax: 0, ay: 0 };
      } else if (game.physicsSystem.applyAttraction(ingredient, player)) {
        this.collectIngredient(ingredient);
      }
    }
  }

  // Returns false (and leaves the ingredient in the world) when the pile is
  // capped for that char. Emerald Robe goo bypasses the pile; Mana fills the
  // meter when it has room and otherwise lands in the pile, which never caps
  // Mana — so Mana is always collected.
  collectIngredient(ingredient) {
    const game = this.game;
    const player = game.player;
    if (ingredient.char === 'g' && player.gooConsume) {
      // Emerald Robe: goo consumed for 1HP heal instead of going to inventory
      player.heal(1);
    } else if (ingredient.char === '𝑚' && game.magicSystem.collectMana(player)) {
      // The meter took it.
    } else if (!game.addIngredient(ingredient.char)) {
      return false;
    }
    game.audioSystem?.playSFX(resolvePickupSfx(ingredient.char));
    game.physicsSystem.removeEntity(ingredient);
    const idx = game.ingredients.indexOf(ingredient);
    if (idx !== -1) game.ingredients.splice(idx, 1);
    return true;
  }

  // REST starter bundle: SPACE near the bundle destroys it and scatters its
  // ingredients in a ring. Returns true if the bundle was in range and burst.
  scatterRestBundle() {
    const game = this.game;
    if (!game.restBundle) return false;
    const dist = Math.hypot(
      game.player.position.x - game.restBundle.position.x,
      game.player.position.y - game.restBundle.position.y
    );
    if (dist >= GRID.CELL_SIZE * 3) return false;
    this.burstRestBundle();
    return true;
  }

  // Burst the Satchel wherever the player is (scatterRestBundle checks the
  // range; TAKE doesn't). Returns the ingredients it scattered.
  burstRestBundle() {
    const game = this.game;
    if (!game.restBundle) return [];
    const cx = game.restBundle.position.x;
    const cy = game.restBundle.position.y;
    const count = game.restBundle.chars.length;
    const scattered = [];
    for (let i = 0; i < count; i++) {
      const angle = (i / count) * Math.PI * 2;
      const r = GRID.CELL_SIZE * (1.5 + Math.random());
      const ing = new Ingredient(
        game.restBundle.chars[i],
        cx + Math.cos(angle) * r,
        cy + Math.sin(angle) * r
      );
      ing.pickupCooldown = 0.25;
      game.ingredients.push(ing);
      game.physicsSystem.addEntity(ing);
      scattered.push(ing);
    }
    game.restBundle = null;
    return scattered;
  }

  spawnLoot(enemy) {
    const game = this.game;

    // An enemy whose only drop is scripted elsewhere (the Gray King's crown,
    // MistBattleSystem) drops nothing here: no roll, no coin, no mana.
    if (enemy.data.noLoot) return;

    // Stolen goods (ThiefMechanic — Rat/Plague Rat coins, Monkey satchel):
    // whatever the thief is still carrying on death goes back to the player
    // unconditionally, not gated by affinities/tier/luck like a natural drop
    // below — killing the thief recovers exactly what it took, no roll
    // involved. Empty/absent for every non-thief enemy, so this is a no-op
    // for them.
    if (enemy.stolenIngredients?.length) {
      for (const char of enemy.stolenIngredients) {
        const angle = Math.random() * Math.PI * 2;
        this.spawnIngredientDrop(char, enemy.position.x, enemy.position.y, angle, enemy);
      }
      enemy.stolenIngredients = [];
    }

    // Luck has two tiers: full-power while Lucky Coin (★) is equipped, half-power
    // under the luck blessing (a green well's raw coin, a fountain, or a held
    // Fortune Dagger — luck.js). The two are independent, but luckActive takes
    // priority on the math.
    // Standing inside Emerald Staff grass (MagicSystem._updateStaffGrassEffects)
    // doubles whatever luck tier is currently active — including the 1.0
    // baseline with no Lucky Coin at all, a standalone loot buff from the grass.
    const player = game.player;
    const grassLuckBoost = player?.inStaffGrass ? 2 : 1;
    const blessed = hasLuckBlessing(player);
    const luckMult    = (player?.luckActive ? 1.75 : (blessed ? 1.375 : 1.0)) * grassLuckBoost;
    const bonusChance = (player?.luckActive ? 0.40 : (blessed ? 0.20 : 0)) * grassLuckBoost;

    let drops = [];
    const affinities = enemy.data.affinities || (enemy.data.dropTable ? [enemy.data.dropTable] : null);
    const tier = enemy.data.tier || enemy.data.rarityProfile;
    if (affinities && tier) {
      // Boss-tier drop count. The flag is read off the instance first, the
      // shared data second: the generic fallback Miniboss and authored
      // BOSS_ENCOUNTERS bosses carry `isBoss` on the entity (roomFeatures
      // spawn paths), while the Centipede head ships its own data object
      // with the flag set (#215 — every Miniboss now qualifies, not just
      // the Centipede).
      const baseDropCount = (enemy.isBoss || enemy.data?.isBoss) ? 3 : null;
      const generatedDrops = generateEnemyDrops(
        affinities,
        tier,
        baseDropCount
      );

      // FIX 3: Apply luckMult to each drop's probability in the affinity path.
      // generateEnemyDrops already selected candidates; filter them by luck-scaled roll.
      // When luckMult === 1.0 every drop passes (Math.random() < 1.0 is always true), so
      // there is no regression for players without luck.
      const luckyDrops = luckMult <= 1.0
        ? generatedDrops
        : generatedDrops.filter(() => Math.random() < Math.min(1.0, luckMult));

      // FIX 4: Bonus drop for luck — derive a valid affinity source instead of relying on
      // the potentially-undefined enemy.data.dropTable.
      if (bonusChance > 0 && Math.random() < bonusChance) {
        const bonusAffinities = enemy.data.affinities || (enemy.data.dropTable ? [enemy.data.dropTable] : null);
        const bonusTier = enemy.data.tier || enemy.data.rarityProfile;
        if (bonusAffinities && bonusTier) {
          const bonusDrop = generateEnemyDrops(bonusAffinities, bonusTier, 1);
          luckyDrops.push(...bonusDrop);
        }
      }

      drops = luckyDrops;
    }

    // Authored `drops` roll on top of the affinity roll, not instead of it —
    // the Bomb's Bomb is in addition to its beast loot. A Bomb that detonated
    // spent the bomb it would have dropped (RipenMechanic `ripenDetonated`).
    if (enemy.data.drops?.length && !enemy.ripenDetonated) {
      for (const drop of enemy.data.drops) {
        const adjustedChance = Math.min(1.0, drop.chance * luckMult);
        if (Math.random() < adjustedChance) {
          drops.push(drop.char);
        }
      }
    }

    // Cursed Run: undead may drop a cursed recipe scroll (CursedRunSystem).
    game.cursedRunSystem.rollScrollDrop(game, enemy);

    // Betrayed Traveler: Shed Key + Coins, once per run (ErrandSystem).
    game.errandSystem.rollSlainDrops(game, enemy);

    // Universal coin chance (bug-inbox 2026-09-18): every enemy has an
    // independent chance (10%, more with a held Fortune Dagger — luck.js) to
    // drop 1 Coin, on top of whatever the affinity/tier or legacy `drops`
    // tooling above already rolled — not scaled by luckMult/bonusChance,
    // since it's deliberately separate from those systems rather than folded
    // into them. One in ten of those Coins is an Empty Bottle instead.
    // A worn Cursed Coin (Cursed Run only) doubles that chance and drops every
    // Gemstone the rolls above produced twice (CursedRunSystem).
    const dropRate = game.cursedRunSystem.dropRateMultiplier(game);
    const baseCoinChance = coinDropChance(player);
    const coinRoll = Math.random();
    if (coinRoll < Math.min(1, baseCoinChance * dropRate)) {
      drops.push(Math.random() < BOTTLE_FOR_COIN_CHANCE ? 'B' : 'c');
    }
    let doubled = coinRoll >= baseCoinChance && coinRoll < baseCoinChance * dropRate;
    if (dropRate > 1) {
      const gems = drops.filter(char => GEM_CHARS.includes(char));
      for (const gem of gems) {
        for (let n = 1; n < dropRate; n++) drops.push(gem);
      }
      if (gems.length) doubled = true;
    }
    if (doubled) game.cursedRunSystem.announceDoubledDrop(game);

    // A beast killed while snared (Snare Trap, Bolo — Enemy.isSnared) always
    // drops a Meat on top of its normal drops: the hunter's catch.
    if (enemy.isSnared?.() && enemy.data.affinities?.includes('beast')) {
      drops.push('m');
    }

    // Mana drop — only once the magic meter is active. 75% chance per kill
    // (100% on bosses) to drop a Mana ingredient (𝑚) that auto-refills the
    // meter on pickup. Skipped when the meter is already full so the player
    // isn't tempted to dawdle for waste drops. Rolled here, not in a death
    // sweep, so every sweep that calls spawnLoot (surface, hut, dungeon)
    // drops it — it used to live only in the surface sweep, so kills inside
    // an interior never dropped mana.
    const meter = player?.magicMeter;
    if (meter?.active && meter.current < meter.max) {
      // Instance flag first (roomFeatures boss spawns), shared data second
      // (Centipede head's own data object) — #215.
      const manaDropChance = (enemy.isBoss || enemy.data?.isBoss) ? 1.0 : 0.75;
      if (Math.random() < manaDropChance) drops.push('𝑚');
    }

    // Frog form: each Coin a kill would drop has a 25% chance to come up a
    // Frog Coin (⊚) instead. Stolen coins returned above stay plain Coins —
    // they were the player's own.
    if (player?.polymorphed) {
      drops = drops.map(d => (d === 'c' && Math.random() < FROG_COIN_SWAP_CHANCE) ? '⊚' : d);
    }

    // Killed while burning (the burn status, or lava's burning pip): the
    // fire already cooked it, so each Meat comes up a Meat Jerky — the
    // Fireplace's Meat recipe (FireplaceSystem), done on the hoof.
    if (enemy.statusEffects?.burn?.active || enemy.inDamagingLiquid) {
      drops = drops.map(d => (d === 'm' ? 'ᒧ' : d));
    }

    for (let i = 0; i < drops.length; i++) {
      const drop = drops[i];
      const angle = (i / Math.max(drops.length, 1)) * Math.PI * 2 + Math.random() * 0.8;
      if (isIngredient(drop)) {
        this.spawnIngredientDrop(drop, enemy.position.x, enemy.position.y, angle, enemy);
      } else if (isItem(drop)) {
        this.spawnItemDrop(drop, enemy.position.x, enemy.position.y, angle, enemy);
      }
    }
  }

  // `source` is the originating entity (enemy or destroyed object). Drops inherit
  // its plane so they spawn on the same layer as the thing they came from.
  spawnIngredientDrop(char, x, y, angle = null, source = null) {
    const ingredient = new Ingredient(char, x, y);
    ingredient.pickupCooldown = 0.75;
    if (source) ingredient.plane = planeOf(source);
    // hutPlane covers both hut and dungeon interiors — they share game.activeFloor and
    // the same overlay render path. Without this, dungeon-spawned loot drops would
    // render at wrong screen coords and slip past the overlay's hutPlane filter.
    tagLootLayer(this.game, ingredient);
    const a = angle !== null ? angle : Math.random() * Math.PI * 2;
    const speed = 60 + Math.random() * 80;
    ingredient.velocity.vx = Math.cos(a) * speed;
    ingredient.velocity.vy = Math.sin(a) * speed;
    this.game.ingredients.push(ingredient);
    this.game.physicsSystem.addEntity(ingredient);
    return ingredient;
  }

  spawnItemDrop(char, x, y, angle = null, source = null) {
    const item = new Item(char, x, y);
    // Found starter potions get the same hidden-ingredient hook as
    // player-crafted ones (Condenser reveal) — random member of the
    // matching ingredient set since the actual brew ingredient is unknown.
    if (STARTER_POTION_CHARS.has(char)) {
      const ingredients = [...starterPotionIngredientsFor(char)];
      const baseIng = ingredients[Math.floor(Math.random() * ingredients.length)];
      item.hiddenIngredient = baseIng;
      item.baseIngredient = baseIng;
    }
    if (source) item.plane = planeOf(source);
    tagLootLayer(this.game, item);
    const a = angle !== null ? angle : Math.random() * Math.PI * 2;
    const speed = 60 + Math.random() * 80;
    item.velocity.vx = Math.cos(a) * speed;
    item.velocity.vy = Math.sin(a) * speed;
    this.game.items.push(item);
    this.game.physicsSystem.addEntity(item);
    return item;
  }
}
