import { GRID } from '../game/GameConfig.js';
import { Item } from '../entities/Item.js';
import { INGREDIENTS } from '../data/items.js';
import { ORE_METAL_CHANCE, STOKE_ASH_CHANCE } from './FireplaceSystem.js';

/**
 * PressSystem — operates the oil press inside huts.
 *
 * Players walk up to a `⊓` press, hit SPACE, and pick a raw oil from the
 * pop-up list. The raw is consumed and a pressed oil is added to the
 * consumable inventory. Some outputs are ingredients instead (Slurry → Paper);
 * those go back to the ingredient pouch. A Clam rolls its own pearls (PRESS_ROLLS):
 * each output rolls independently at the same chance the fireplace gives Metal
 * from Ore and Ash from sticks.
 *
 * Forest Berries press into Berry Juice: BERRIES_PER_JUICE berries and an
 * Empty Bottle, which the juice fills where it sits.
 */

const PRESS_TABLE = {
  'ŝ': '🜁',  // Sap        → Slick Oil
  'š': '🜂',  // Fire Sap   → Fire Oil
  'ş': '❄',  // Frost Sap  → Frost Oil
  'ł': '🜔',  // Pollen     → Drowse Oil
  '⚗': 'N',  // Slurry     → Paper (ingredient)
};

// Raws that press into several independent ingredients. Each entry rolls on its
// own; a miss on every roll presses out nothing.
const PRESS_ROLLS = {
  'C': [
    { char: '●', chance: ORE_METAL_CHANCE },  // Pearl (Metal's roll)
    { char: 'p', chance: STOKE_ASH_CHANCE }   // Pearl Shard (Ash's roll)
  ]
};

const FOREST_BERRY_CHAR = '⁖';
const BERRY_JUICE_CHAR = '⁘';
const BERRIES_PER_JUICE = 3;

const INTERACT_RADIUS = GRID.CELL_SIZE * 1.2;

export class PressSystem {
  constructor(game) {
    this.game = game;
  }

  /** True if the player is adjacent to a press object inside the active hut. */
  nearPress() {
    const game = this.game;
    if (!game.player?.inHut || !game.activeFloor) return false;
    const C = GRID.CELL_SIZE;
    const px = game.player.position.x + C / 2;
    const py = game.player.position.y + C / 2;
    for (const obj of game.activeFloor.backgroundObjects) {
      if (obj.char !== '⊓' || obj.destroyed) continue;
      const cx = obj.position.x + C / 2;
      const cy = obj.position.y + C / 2;
      const dx = px - cx, dy = py - cy;
      if (Math.sqrt(dx * dx + dy * dy) < INTERACT_RADIUS) return true;
    }
    return false;
  }

  /** SPACE near a press → open the press menu. */
  handleSpacePress() {
    if (!this.nearPress()) return false;
    this.openPressMenu();
    return true;
  }

  openPressMenu() {
    const game = this.game;
    const counts = new Map();
    const pressable = [];
    for (const ch of game.getIngredients()) {
      if (!PRESS_TABLE[ch] && !PRESS_ROLLS[ch]) continue;
      counts.set(ch, (counts.get(ch) ?? 0) + 1);
      if (!pressable.includes(ch)) pressable.push(ch);
    }

    const berryCount = game.inventorySystem.countConsumable(FOREST_BERRY_CHAR);
    if (berryCount >= BERRIES_PER_JUICE && game.bottlesSystem.emptyBottleRef()) {
      counts.set(FOREST_BERRY_CHAR, berryCount);
      pressable.push(FOREST_BERRY_CHAR);
    }

    if (pressable.length === 0) {
      game.menuSystem.showPickupMessage('NOTHING TO PRESS');
      return;
    }

    game.menuOpen = true;
    game.currentMenuSlot = 'press';
    game.selectedMenuIndex = 0;
    game.menuItems = pressable;
    game.ingredientCounts = counts;
    game.renderController.menuOverlay.render(game);
    game.menuSystem.closeOnMovement = true;
  }

  /** Commit the press: consume one raw, drop the output into consumables (or ingredients). */
  commitSelection(rawChar) {
    const game = this.game;
    if (rawChar === FOREST_BERRY_CHAR) { this._pressJuice(); return; }
    const outChar = PRESS_TABLE[rawChar];
    const rolls = PRESS_ROLLS[rawChar];
    if (!outChar && !rolls) return;

    if (!game.removeIngredient(rawChar)) return;

    if (rolls) {
      for (const { char, chance } of rolls) {
        if (Math.random() >= chance) continue;
        game.addIngredient(char);
        game.menuSystem.announceCrafted(char);
      }
      game.audioSystem?.playSFX?.('craft');
      game.closeMenu();
      game.updateUI();
      return;
    }

    if (INGREDIENTS[outChar]) {
      game.addIngredient(outChar);
      game.menuSystem.announceCrafted(outChar);
    } else {
      const oil = new Item(outChar, game.player.position.x, game.player.position.y);
      const stacked = game.inventorySystem.stowConsumable(oil, game.player);
      game.menuSystem.announceCrafted(oil.char, stacked);
    }
    game.audioSystem?.playSFX?.('craft');
    game.closeMenu();
    game.updateUI();
  }

  // Three berries into the Empty Bottle: the juice takes the bottle's place.
  _pressJuice() {
    const game = this.game;
    const inv = game.inventorySystem;
    const bottle = game.bottlesSystem.emptyBottleRef();
    if (!bottle || inv.countConsumable(FOREST_BERRY_CHAR) < BERRIES_PER_JUICE) return;
    for (let i = 0; i < BERRIES_PER_JUICE; i++) inv.removeOneConsumable(FOREST_BERRY_CHAR);
    game.bottlesSystem.replaceAt(bottle, BERRY_JUICE_CHAR);
    game.menuSystem.announceCrafted(BERRY_JUICE_CHAR);
    game.audioSystem?.playSFX?.('craft');
    game.closeMenu();
    game.updateUI();
  }
}
