import { GRID } from '../../game/GameConfig.js';
import { inSamePlane } from '../../systems/PlaneSystem.js';
import { ThiefMechanic } from './ThiefMechanic.js';
import { commitAttack } from '../enemyDecision.js';

// Giant Slime leap: 3-phase sequence (windup → airborne → cooldown). Airborne
// lerps from a snapshot start to a target snapshot taken at windup completion.
// Both windup AND airborne fully suspend Enemy.update() — no other AI runs.
//
// Two call sites in Enemy.update():
//   - updateActive(): early, before status overrides. Handles windup hold and
//     the airborne arc; returns suspend payload while in either phase.
//   - tryTrigger(): after distance calc. If conditions are met (cooldown ready,
//     not spewing, in leap-trigger range, same plane), starts the windup and
//     returns a suspend signal.
//
// `cfg.steal` makes the leap a Thief's grab (Monkey): the leap only fires
// while ThiefMechanic.canLeapSteal holds and lands a steal, not a shockwave
// (EnemyUpdateSystem._handleLeapLand). Its aim is locked at windup start like
// every leap — the windup line is the promise, so the leap never homes.
//
// `cfg.holdTime` makes the Enemy keep its distance first (Frost Wolf): it must
// hold leap range continuously for that many enemy timer seconds (data units,
// half of real time, PHYSICS.ENEMY_TIMER_RATE) before it can launch.
// Each aggroed packmate shortens the hold by `cfg.holdPerMate` (floor
// `cfg.holdMin`), so a pack commits to its leaps sooner than a lone wolf.
// `cfg.hop` makes the leap only a way to close distance (Bumper): it lands
// with no impact (no landing hit, shockwave, or landing SFX), since
// whatever the Enemy does on arrival is its threat.
// `cfg.counterLeap: false` stops a struck Enemy answering with an immediate
// leap, which would skip the hold.

// How long a holding Enemy must stay in leap range before it may launch.
function holdRequired(enemy, cfg) {
  const aggroedMates = (enemy.packmates ?? []).filter(m => !m.isDying && m.enraged).length;
  return Math.max(cfg.holdMin ?? 0, cfg.holdTime - (cfg.holdPerMate ?? 0) * aggroedMates);
}

// Point a leap at `target`. A dizzy leaper misjudges its landing, so a
// player-aimed vector is rotated by the dizzy offset.
function aimLeap(enemy, target, dizzyOffset) {
  enemy.leapTargetX = target.x;
  enemy.leapTargetY = target.y;
  if (dizzyOffset) {
    const ldx = target.x - enemy.position.x;
    const ldy = target.y - enemy.position.y;
    const cos = Math.cos(dizzyOffset), sin = Math.sin(dizzyOffset);
    enemy.leapTargetX = enemy.position.x + ldx * cos - ldy * sin;
    enemy.leapTargetY = enemy.position.y + ldx * sin + ldy * cos;
  }
}

export const LeapAttackMechanic = {
  isEnabled(enemy) {
    return enemy.data.leapAttack?.enabled === true;
  },

  init(enemy) {
    enemy.leapCooldown = 2.0; // brief grace at spawn
    enemy.leapHoldTimer = 0; // seconds held in leap range (cfg.holdTime)
    enemy.forcedLeapPending = false; // armed by Enemy.takeDamage; consumed the frame iframes expire
    enemy.leapWindupActive = false;
    enemy.leapWindupTimer = 0;
    enemy.leapWindupDuration = 0; // full length of the windup in progress (LungeTelegraphDraw fades its line across it)
    enemy.leapAirborneActive = false;
    enemy.leapAirTimer = 0;
    enemy.leapAirDuration = 0;
    enemy.leapStartX = 0;
    enemy.leapStartY = 0;
    enemy.leapTargetX = 0;
    enemy.leapTargetY = 0;
    enemy.leapArcLift = 0;
    // Imbue Pools (ImbuePoolSystem): the pool a forced leap should aim at
    // instead of the player, and the pool the leap in flight is aimed at.
    enemy.leapPoolTarget = null;
    enemy.leapPool = null;
  },

  // Early-phase update: cooldown tick + windup/airborne handling.
  updateActive(enemy, ctx) {
    const cfg = enemy.data.leapAttack;
    if (!cfg?.enabled) return;
    const { deltaTime, dotDamageEvents } = ctx;

    if (enemy.leapCooldown > 0) {
      enemy.leapCooldown = Math.max(0, enemy.leapCooldown - deltaTime);
    }

    if (enemy.leapAirborneActive) {
      enemy.leapAirTimer -= deltaTime;
      const dur = enemy.leapAirDuration || cfg.airTime || 0.5;
      const t = Math.min(1, 1 - enemy.leapAirTimer / dur);
      enemy.position.x = enemy.leapStartX + (enemy.leapTargetX - enemy.leapStartX) * t;
      enemy.position.y = enemy.leapStartY + (enemy.leapTargetY - enemy.leapStartY) * t;
      enemy.leapArcLift = Math.sin(t * Math.PI) * (cfg.arcLift || GRID.CELL_SIZE * 1.5);
      enemy.velocity.vx = 0;
      enemy.velocity.vy = 0;
      if (enemy.targetVelocity) { enemy.targetVelocity.vx = 0; enemy.targetVelocity.vy = 0; }
      if (enemy.leapAirTimer <= 0) {
        enemy.leapAirborneActive = false;
        enemy.leapArcLift = 0;
        enemy.position.x = enemy.leapTargetX;
        enemy.position.y = enemy.leapTargetY;
        enemy.leapCooldown = cfg.cooldown;
        const landedPool = enemy.leapPool;
        enemy.leapPool = null;
        if (cfg.hop) return { suspend: true, result: { dotDamage: dotDamageEvents } };
        return {
          suspend: true,
          result: {
            dotDamage: dotDamageEvents,
            shouldLeapLand: true,
            leapLandData: {
              x: enemy.leapTargetX + GRID.CELL_SIZE / 2,
              y: enemy.leapTargetY + GRID.CELL_SIZE / 2,
              cfg,
              plane: enemy.plane ?? 0,
              pool: landedPool
            }
          }
        };
      }
      return { suspend: true, result: { dotDamage: dotDamageEvents } };
    }

    if (enemy.leapWindupActive) {
      // Lost visibility mid-windup — cancel rather than let the leap fire
      // unseen. Free retry (no cooldown charge), same idiom as an aborted
      // Strike windup: nothing was actually spent.
      if (!ctx.onScreen || (cfg.steal && !ThiefMechanic.canLeapSteal(enemy))) {
        enemy.leapWindupActive = false;
        enemy.leapWindupTimer = 0;
        return { suspend: true, result: { dotDamage: dotDamageEvents } };
      }
      enemy.leapWindupTimer -= deltaTime;
      enemy.velocity.vx = 0;
      enemy.velocity.vy = 0;
      if (enemy.targetVelocity) { enemy.targetVelocity.vx = 0; enemy.targetVelocity.vy = 0; }
      if (enemy.leapWindupTimer <= 0) {
        enemy.leapWindupActive = false;
        enemy.leapStartX = enemy.position.x;
        enemy.leapStartY = enemy.position.y;
        enemy.leapAirDuration = cfg.airTime;
        enemy.leapAirTimer = enemy.leapAirDuration;
        enemy.leapAirborneActive = true;
        if (cfg.takeoffSfx) enemy.game?.audioSystem?.playSFX?.(cfg.takeoffSfx);
      }
      return { suspend: true, result: { dotDamage: dotDamageEvents } };
    }
  },

  // Called from Enemy.takeDamage on a non-lethal hit, as its iframes start.
  // Arms a forced leap for the instant these iframes expire — see tryTrigger.
  // No-op for enemies without leapAttack. One hit, one answering leap: a hit
  // taken mid-leap (windup or airborne) doesn't queue another leap for the
  // landing.
  onDamaged(enemy) {
    if (enemy.data?.leapAttack?.enabled && !enemy.data.leapAttack.steal &&
        enemy.data.leapAttack.counterLeap !== false &&
        !enemy.leapWindupActive && !enemy.leapAirborneActive) {
      enemy.forcedLeapPending = true;
    }
  },

  /**
   * Cancel a leap still in its windup and pay the full cooldown, the same
   * contract as ChargeMechanic.interrupt: sleep, stun, freeze, zap and
   * knockback end the squat instead of letting it launch the moment the
   * Enemy recovers. A leap already airborne is committed and lands. No-op
   * when idle.
   */
  interrupt(enemy) {
    const cfg = enemy.data?.leapAttack;
    if (!cfg?.enabled || !enemy.leapWindupActive) return;
    enemy.leapWindupActive = false;
    enemy.leapWindupTimer = 0;
    enemy.leapHoldTimer = 0;
    enemy.forcedLeapPending = false;
    enemy.leapPool = null;
    enemy.leapCooldown = cfg.cooldown;
  },

  // Mid-phase trigger: check if conditions are met to start a new leap.
  tryTrigger(enemy, ctx) {
    const cfg = enemy.data.leapAttack;
    if (!cfg?.enabled) return;
    const { effectiveDistance, dotDamageEvents, deltaTime } = ctx;
    const inRange = effectiveDistance >= cfg.triggerRangeMin && effectiveDistance <= cfg.triggerRangeMax;

    // The distance hold is continuous: it runs only while the target is in
    // range, in plane and on screen, and any break starts it over. Ticked
    // before the early returns below so none of them can leave it running.
    if (cfg.holdTime) {
      const holding = inRange && ctx.onScreen && inSamePlane(enemy, enemy.target);
      enemy.leapHoldTimer = holding ? enemy.leapHoldTimer + deltaTime : 0;
    }

    if (enemy.spewWindupActive) return;
    if (cfg.steal && !ThiefMechanic.canLeapSteal(enemy)) return;
    // Wet, it can't leap at all — not even the counter-leap a hit arms.
    if (enemy.isWet()) { enemy.forcedLeapPending = false; return; }
    if (!inSamePlane(enemy, enemy.target)) return;
    if (!ctx.onScreen) return; // no ambushing from outside the zoomed frame

    // Counterattack: a landed hit arms forcedLeapPending (Enemy.takeDamage).
    // The instant this boss's own post-hit iframes expire, the leap fires
    // immediately — regardless of the normal cooldown/trigger-range gate —
    // so every hit that lands is answered with a forced reposition instead
    // of leaving the boss standing still to be melee-spammed. onScreen/plane/
    // spewWindupActive above still gate it; only cooldown and range are
    // bypassed.
    const forced = enemy.forcedLeapPending && enemy.invulnerabilityTimer <= 0;
    if (!forced && (enemy.leapCooldown > 0 || !inRange)) return;
    if (cfg.holdTime && enemy.leapHoldTimer < holdRequired(enemy, cfg)) return;
    // Even the counter-leap a hit arms waits for a Decision Frame: answering
    // a blow is still a decision (enemyDecision.js).
    if (!commitAttack(enemy)) return;

    // Windup scales down with lost HP — full HP leaps at cfg.windupTime,
    // 0 HP leaps at half that, linear in between. Makes the boss leap
    // noticeably more often as it's worn down instead of at a flat cadence.
    const hpFraction = enemy.maxHp > 0 ? Math.max(0, Math.min(1, enemy.hp / enemy.maxHp)) : 1;
    enemy.leapWindupActive = true;
    enemy.leapWindupTimer = cfg.windupTime * (0.5 + 0.5 * hpFraction);
    enemy.leapWindupDuration = enemy.leapWindupTimer;
    // A forced leap from an un-imbued slime may aim at an Imbue Pool instead
    // (leapPoolTarget, set by ImbuePoolSystem) — otherwise at the player.
    const pool = forced ? enemy.leapPoolTarget : null;
    const target = pool ? pool.center : enemy.target.position;
    enemy.leapPool = pool ?? null;
    enemy.leapPoolTarget = null;
    // A pool leap is a deliberate target, so dizziness leaves it alone.
    aimLeap(enemy, target, pool ? 0 : enemy._dizzyAngleOffset());
    enemy.velocity.vx = 0;
    enemy.velocity.vy = 0;
    if (enemy.targetVelocity) { enemy.targetVelocity.vx = 0; enemy.targetVelocity.vy = 0; }
    enemy.forcedLeapPending = false;
    enemy.leapHoldTimer = 0;
    return { suspend: true, result: { dotDamage: dotDamageEvents } };
  }
};
