import { inSamePlane } from './PlaneSystem.js';
import { NeutralCharacter } from '../entities/NeutralCharacter.js';
import { CAMP_NPC_STATE } from '../entities/CampNPC.js';
import { MAX_PIPS, clearStatusEffect } from './StatusEffects.js';

/** What an NPC without its own refusal line says to PERSUADE. */
const DEFAULT_REFUSAL = 'I HAVE NOTHING.';

/**
 * InfluenceSystem — the Influence Wish Spells, which act on the nearest
 * speaker (claudedocs/three-voice-plan.md §8).
 *
 * PERSUADE: the NPC answers before any wish is asked for. What it does is data
 * on the NPC (NeutralCharacter `persuadeOwner` / `persuadeRefusal`), carried
 * out by the NPC's owning system:
 *   - `persuadeOwner` names a game system implementing
 *     `persuadeRefusal(npc)` → string|null (null = accepts) and
 *     `persuade(npc)`, which runs that NPC's transaction without its cost.
 *   - Without an owner the NPC refuses with `persuadeRefusal`.
 * A refusal spends nothing. Accepted, the wish question follows; YES spends
 * the wish and runs persuade().
 *
 * COMMAND, near an NPC: the NPC joins as the companion (CampNPCSystem
 * .hireFollower) for a wish. Away from NPCs COMMAND asks for a true name and
 * charms an enemy for free (CommandSystem). Charon at his post can't be
 * commanded; a companion already following refuses the word before any wish.
 *
 * CHARM: every enemy in the room fights the others until the room is left
 * (`Enemy.wishCharmed` keeps the player out of its reach, as for a commanded
 * unit). SLEEP: every enemy in the room falls fully asleep until struck — the
 * sleep status's own wake-on-damage ends it. Both refuse with no enemy near.
 *
 * The speaker is found again on every call; the only state is the charmed
 * roster, which reset() hands back when the room is left.
 */
export class InfluenceSystem {
  constructor(game) {
    this.game = game;
    /** Enemies the CHARM wish turned, released on room exit. */
    this.charmed = [];
  }

  reset() {
    for (const enemy of this.charmed) {
      enemy.wishCharmed = false;
      clearStatusEffect(enemy, 'charm');
    }
    this.charmed = [];
  }

  /**
   * The nearest NPC in talking range on the player's plane — the room's or
   * floor's NPCs, and Charon at REST's north exit.
   */
  nearestNpc({ withCharon = true } = {}) {
    const game = this.game;
    const player = game.player;
    if (!player) return null;
    const npcs = [...game.interiorManager.activeNpcs()];
    if (withCharon && game.charon?.npc) npcs.push(game.charon.npc);

    let nearest = null;
    let nearestDist = Infinity;
    for (const npc of npcs) {
      if (!npc.isInRange?.(player) || !inSamePlane(npc, player)) continue;
      const dist = Math.hypot(player.position.x - npc.position.x, player.position.y - npc.position.y);
      if (dist < nearestDist) {
        nearest = npc;
        nearestDist = dist;
      }
    }
    return nearest;
  }

  _persuadeOwner(npc) {
    return npc?.persuadeOwner ? this.game[npc.persuadeOwner] : null;
  }

  /** PERSUADE's refusal, or null when the nearest NPC accepts. */
  persuadeRefusal() {
    const npc = this.nearestNpc();
    if (!npc) return 'NO ONE.';
    const owner = this._persuadeOwner(npc);
    if (!owner) return npc.persuadeRefusal ?? DEFAULT_REFUSAL;
    return owner.persuadeRefusal(npc);
  }

  /** The wish was spent: the nearest NPC's transaction happens without its cost. */
  persuade() {
    const npc = this.nearestNpc();
    const owner = this._persuadeOwner(npc);
    if (owner && !owner.persuadeRefusal(npc)) owner.persuade(npc);
  }

  // ── COMMAND ──────────────────────────────────────────────────────────────────

  /** The NPC COMMAND would take: the nearest one in range, Charon excepted. */
  commandTarget() {
    const npc = this.nearestNpc({ withCharon: false });
    return npc instanceof NeutralCharacter ? npc : null;
  }

  /** COMMAND's refusal near an NPC, or null when the NPC would join. */
  commandRefusal() {
    const companion = this.game.companion;
    return companion && companion.state !== CAMP_NPC_STATE.FLEEING ? 'ONE FOLLOWS.' : null;
  }

  /**
   * COMMAND's YES: spend the wish and take the nearest NPC off its room or
   * floor as the companion. The return value is the THREE's line.
   */
  command() {
    const game = this.game;
    const npc = this.commandTarget();
    if (!npc || this.commandRefusal() || !game.wishSystem.spend(game)) return '...NOTHING.';

    game.campNPCSystem.takeFollower(npc);
    return 'AS YOU WISH.';
  }

  // ── CHARM / SLEEP ────────────────────────────────────────────────────────────

  /** The room's (or floor's) living enemies. */
  _roomEnemies() {
    return (this.game._activeEnemies() ?? []).filter(e => !e.isDying && e.hp > 0);
  }

  /** CHARM and SLEEP's refusal: nothing to bend. */
  roomRefusal() {
    return this._roomEnemies().length ? null : '...NOTHING.';
  }

  /** The wish was spent: every enemy in the room turns on the others. */
  charmRoom() {
    for (const enemy of this._roomEnemies()) {
      enemy.applyStatusEffect?.('charm', Infinity, MAX_PIPS);
      if (!enemy.isCharmed?.()) continue; // charm-immune
      enemy.wishCharmed = true;
      this.charmed.push(enemy);
    }
  }

  /** The wish was spent: every enemy in the room falls asleep until struck. */
  sleepRoom() {
    for (const enemy of this._roomEnemies()) enemy.applyStatusEffect?.('sleep', Infinity, MAX_PIPS);
  }
}
